using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RetainerReleaseTests
{
    static EntityId Person=>HistoricalHouseholdCatalog.Edition.People.Single().Id;static EntityId Lord=>HistoricalHouseholdCatalog.Edition.People.Single().Lord;
    static WorldSession Start(bool modern=true,bool consent=true){var d=PrivateInspectionTests.Start().DiagnosticSnapshot().NewGame!;var w=NewGameWorld.Create(d.Start,d.Registered,d.Selected.Value,historicalCatalog:d.HistoricalCatalog,npcRoutinePolicy:d.NpcRoutinePolicy,inspectionPolicy:d.InspectionPolicy,workPolicy:d.WorkPolicy,companionPolicy:modern?PersonalCompanions.RetainerReleasePolicy:PersonalCompanions.PersonalServicePolicy,informationPolicy:d.InformationPolicy);if(!consent)w.Characters=w.Characters.Select(c=>c.Id==Lord?c with{WillObey=false}:c).ToArray();return new(w);}
    static void At(WorldSession s,long t)=>PersonalCompanionTests.Advance(s,t);
    static CommandResult Act(WorldSession s,CompanionAction a,long money=0,string? id=null)=>s.ManageCompanion(new(new(id??"request:old-lord/"+s.Revision),Person,a,money),s.PlayerControl,s.Revision);
    static void Prepare(WorldSession s){PrivateInspectionTests.Contact(s);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.PrivateInspect,20).Code);At(s,17);var msg=s.DiagnosticSnapshot().Companions!.Reports.Single().Message;Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(msg),s.Revision).Code);}
    static void Ask(WorldSession s,string? id=null){var r=Act(s,CompanionAction.RequestLordRelease,id:id);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void OpenNotice(WorldSession s){var m=s.DiagnosticSnapshot().Messaging.Messages.Last(m=>m.Kind==PersonalCompanions.ReleaseNoticeKind);Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(m.Id),s.Revision).Code);}
    [Fact]public void RequestDoesNotReleaseAndActualConsentReceiptPrecedesPlayerRecognition(){var s=Start();Prepare(s);var b=s.DiagnosticSnapshot();Ask(s);Assert.Equal(ContractJson.Write(b.ServiceBonds),ContractJson.Write(s.DiagnosticSnapshot().ServiceBonds));At(s,18);Assert.Contains(s.DiagnosticSnapshot().Companions!.Orders,o=>o.Input.Action==CompanionAction.LordReleaseApproved);Assert.Contains(s.DiagnosticSnapshot().ServiceBonds,r=>r.Subject==Person&&r.Until==long.MaxValue);At(s,19);var w=s.DiagnosticSnapshot();Assert.Contains(w.ServiceBonds,r=>r.Subject==Person&&r.Target==Lord&&r.Until==19);Assert.Contains(w.Memberships,r=>r.Subject==Person&&r.Until==19);Assert.False(s.RetainerReleaseView().Single().KnownReleased);Assert.Equal("一件だけの私的点検協力",s.CompanionView().Single(c=>c.Person==Person).Kind);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Agree,20).Code);At(s,20);OpenNotice(s);Assert.True(s.RetainerReleaseView().Single().KnownReleased);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Agree,20).Code);}
    [Fact]public void OldLordsRefusalKeepsHouseServiceWalletAndNoAutomaticWar(){var s=Start(consent:false);Prepare(s);var b=s.DiagnosticSnapshot();Ask(s);At(s,22);OpenNotice(s);var w=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(b.Memberships),ContractJson.Write(w.Memberships));Assert.Equal(ContractJson.Write(b.ServiceBonds),ContractJson.Write(w.ServiceBonds));Assert.False(s.RetainerReleaseView().Single().KnownReleased);Assert.Equal(960,NewGameWork.Balance(w,s.PlayerControl));Assert.Null(w.FactionStances);Assert.Empty(w.Units);}
    [Fact]public void BusyLordWaitsForHisOwnWorkWithoutLeakingIt(){var s=Start();Prepare(s);Assert.Equal(ResultCode.Accepted,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),"request:lord-busy") with{Actor=Lord,Executor=Lord},s.Revision).Code);Ask(s);At(s,20);Assert.DoesNotContain(s.DiagnosticSnapshot().Companions!.Orders,o=>o.Input.Action==CompanionAction.LordReleaseApproved);Assert.Equal("本人が旧主へ申し出・結果の通知待ち",s.RetainerReleaseView().Single().Status);At(s,30);OpenNotice(s);Assert.True(s.RetainerReleaseView().Single().KnownReleased);}
    [Fact]public void NoPaidContactOrUnreadWorkReportDoesNotRequestRelease(){var s=Start();At(s,8);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.RequestLordRelease).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));PrivateInspectionTests.Contact(s);Act(s,CompanionAction.PrivateInspect,20);At(s,17);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.RequestLordRelease).Code);}
    [Fact]public void RepeatedRequestCannotDuplicatePapersOrEndings(){var s=Start();Prepare(s);Ask(s,"request:release-stable");Assert.Equal(ResultCode.AlreadyAccepted,Act(s,CompanionAction.RequestLordRelease,id:"request:release-stable").Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.RequestLordRelease).Code);At(s,25);Assert.Single(s.DiagnosticSnapshot().Companions!.Orders,o=>o.Input.Action==CompanionAction.LordReleaseReceived);Assert.Equal(3,s.DiagnosticSnapshot().Messaging.Messages.Count(m=>m.Kind.StartsWith("retainer-release-")));}
    [Theory][InlineData(CompanionAction.LordReleaseApproved)][InlineData(CompanionAction.LordReleaseRefused)][InlineData(CompanionAction.LordReleaseReceived)][InlineData(CompanionAction.LordRefusalReceived)]public void PlayerCannotForgeNpcDecision(CompanionAction action){var s=Start();Prepare(s);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,action).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ReleasedPersonCanSeparatelyAgreeToServePlayerWithoutMovingLandTroopsOrMemory(){var s=Start();Prepare(s);var b=s.DiagnosticSnapshot();Ask(s);At(s,22);OpenNotice(s);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Agree,20).Code);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.PledgeService).Code);var w=s.DiagnosticSnapshot();Assert.Contains(w.ServiceBonds,r=>r.Subject==Person&&r.Target==s.PlayerControl&&r.Until==long.MaxValue);Assert.Equal(ContractJson.Write(b.LandRights),ContractJson.Write(w.LandRights));Assert.Equal(ContractJson.Write(b.Grants),ContractJson.Write(w.Grants));Assert.Empty(w.Units);Assert.Contains(w.Evidence,e=>e.Observer==Person&&e.Claim.StartsWith("route-open:"));Assert.Equal(940,NewGameWork.Balance(w,s.PlayerControl));Assert.DoesNotContain(w.Memberships,m=>m.Subject==Person&&m.Until==long.MaxValue);}
    [Fact]public void ActualSavesRestoreRequestReplyAndKnownReleaseThenSameFuture(){var s=Start();Prepare(s);Ask(s);var restored=Restore(s,"request");Export(s,restored,"retainer-release-request");At(s,18);At(restored,18);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));restored=Restore(s,"reply");Export(s,restored,"retainer-release-reply");At(s,22);At(restored,22);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));OpenNotice(s);restored=Restore(s,"known");Export(s,restored,"retainer-release-known");Assert.Equal(ContractJson.Write(s.RetainerReleaseView()),ContractJson.Write(restored.RetainerReleaseView()));Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Agree,20).Code);Assert.Equal(ResultCode.Accepted,Act(restored,CompanionAction.Agree,20).Code);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.PledgeService).Code);Assert.Equal(ResultCode.Accepted,Act(restored,CompanionAction.PledgeService).Code);At(s,30);At(restored,30);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));}
    [Fact]public void OldPolicyRetainsWorldBytesAndRejectsRelease(){var s=Start(false);Prepare(s);var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.RequestLordRelease).Code);Assert.Equal(b,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));}
    [Fact]public void ForgedLetterRecipientAndEarlyEndCannotLoad(){var s=Start();Prepare(s);Ask(s);At(s,22);var w=s.DiagnosticSnapshot();w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Kind=="retainer-release-reply"?m with{RecipientId=s.PlayerControl.Value}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.ServiceBonds=w.ServiceBonds.Select(r=>r.Subject==Person?r with{Until=18}:r).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void NoticeStaysAtOriginalMeetingInsteadOfFollowingPlayerGps(){var s=Start();Prepare(s);Ask(s);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:release-away","suwa"),s.Revision).Code);At(s,22);var w=s.DiagnosticSnapshot();var m=w.Messaging.Messages.Single(m=>m.Kind==PersonalCompanions.ReleaseNoticeKind);Assert.Equal("kofu",NewGameWorld.Address(w,m));Assert.Equal(ResultCode.NotAvailable,s.Open(s.PlayerControl,new(m.Id),s.Revision).Code);Assert.False(s.RetainerReleaseView().Single().KnownReleased);At(s,w.Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt);Assert.Equal("kofu",NewGameWorld.Address(s.DiagnosticSnapshot(),m));Assert.Equal(ResultCode.NotAvailable,s.Open(s.PlayerControl,new(m.Id),s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:release-return","kofu"),s.Revision).Code);At(s,s.Seconds+1);At(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.InquireLordRelease).Code);At(s,s.Seconds+1);OpenNotice(s);Assert.True(s.RetainerReleaseView().Single().KnownReleased);Assert.Single(s.DiagnosticSnapshot().Companions!.Orders,o=>o.Input.Action==CompanionAction.LordReleaseReceived);}
    static WorldSession Restore(WorldSession s,string slot){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"retainer-release-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,slot,w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare(slot),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));return host.Current;}
    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrWhiteSpace(dir))return;Directory.CreateDirectory(dir);foreach(var x in new[]{(s:a,t:"before"),(s:b,t:"restored")})File.WriteAllBytes(Path.Combine(dir,name+"."+x.t+".json"),ContractJson.Write(x.s.DiagnosticSnapshot()));}
}
